g=[[8]*23 for _ in range(27)]
# frames (top row, color, number of satellite components)
for top,color,n in [(1,2,2),(7,4,4),(13,3,1),(19,1,1)]:
    left,right=1,11
    for c in range(left,right+1):
        g[top][c]=color; g[top+4][c]=color
    for r in range(top,top+5):
        g[r][left]=color; g[r][right]=color
    mid=top+2
    for c in range(right-2, right-2*n, -2):
        g[mid][c]=color
print('\n'.join(' '.join(map(str,row)) for row in g))
